"""RoboPaint reference painting. All motion uses the public Robot client.
The interactive execution records every command and action array under output.
Run with --replay to replay this recorded motion only in a new authorized episode.
"""
import sys,time,json,traceback,os
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output')
class Painter:
 def __init__(self):
  self.r=Robot();self.spec=self.r.spec();self.o=self.r.get_obs(cameras=[],video='none')
  self.pose=np.array(self.o.meta['proprio']['now'][7:14]);self.quat=self.pose[3:].copy();self.seq=0;self.strokes=0
 def send(self,poses,note='',cameras=[]):
  poses=np.array(poses)
  results=[]
  for start in range(0,len(poses),180):
   a=poses[start:start+180];self.seq+=1
   np.save(ROOT/f'actions/{self.seq:05d}.npy',a)
   before=self.r.status()
   try: res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video='none',note=note)
   except Exception as e:
    print('ERROR',repr(e),flush=True);status=self.r.wait_ready();print(status,flush=True)
    if status['control_steps']==before['control_steps']:
     res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video='none',note=note)
    else:
     res=self.r.get_obs(cameras=cameras,video='none')
   self.o=res;self.pose=np.array(res.meta['proprio']['now'][7:14]);results.append(res)
   (ROOT/f'actions/{self.seq:05d}.json').write_text(json.dumps(res.meta))
   print('CALL',self.seq,'rows',len(a),'tip',np.round(self.pose[:3],5),'left',res.meta.get('time_left_s'),'plan',res.meta.get('plan'),flush=True)
   if res.done or res.stopped:raise RuntimeError(str(res.meta))
  return results[-1] if results else None
 def path(self,xyz,speed=.08,hold=.2):
  xyz=np.asarray(xyz);ps=[];prev=self.pose[:3].copy()
  for p in xyz:
   n=max(1,int(np.ceil(np.linalg.norm(p-prev)/speed/.05)))
   for t in np.linspace(0,1,n+1)[1:]:ps.append(np.r_[prev+(p-prev)*t,self.quat])
   prev=p
  for _ in range(round(hold/.05)):ps.append(np.r_[prev,self.quat])
  return self.send(ps)
 def obs(self,name,cameras=['canvas_cam','scene_cam','side_cam','practice_cam'],depth=False):
  o=self.r.get_obs(cameras=cameras,depth=depth,video='none');self.o=o;o.save('/app/runs/'+name)
  for c,a in o.last.items():Image.fromarray(a).save('/app/runs/'+name+'/'+c+'.png')
  return o
 def park(self):return self.path([[self.pose[0],self.pose[1],.075],[-.31,0,.075]],speed=.15,hold=.5)

def main():
 (ROOT/'actions').mkdir(exist_ok=True);(ROOT/'jobs').mkdir(exist_ok=True)
 p=Painter();env={'p':p,'r':p.r,'np':np,'Image':Image,'json':json,'Path':Path,'time':time}
 if '--replay' in sys.argv:
  for f in sorted((ROOT/'actions').glob('*.npy')):p.r.submit('ee_pose',np.load(f),dt=.05,cameras=[],video='none')
  return
 print('READY',p.pose,flush=True)
 while True:
  files=sorted((ROOT/'jobs').glob('*.py'))
  for f in files:
   if f.with_suffix('.done').exists():continue
   print('JOB',f,flush=True)
   try:exec(compile(f.read_text(),str(f),'exec'),env);f.with_suffix('.done').write_text('ok')
   except Exception:traceback.print_exc();f.with_suffix('.done').write_text(traceback.format_exc())
  time.sleep(.3)
if __name__=='__main__':main()
